                    std::cerr << " a" << di << "(t=" << static_cast<int>(args[di].type)
                              << ",i=" << args[di].int_val
                              << ",s=\"" << (args[di].type == DalvikType::STRING_REF ? std::string(args[di].string_val) : std::string(""))
                              << "\")";
