    // ────────────────────────────────────────────────────────────────────────
    // P1.3b — TimeUnit conversions (F-023 duration law)
    // java.util.concurrent.TimeUnit.toNanos/toMillis/toSeconds/toMinutes/
    // toHours/toDays/convert — AOSP semantics: convert the source duration
    // to nanos via the receiver unit's multiplier, then scale to the target
    // unit (saturating at Long extremes like AOSP's overflow handling).
    // Real-world impact: kotlinx.coroutines Dispatchers.Default
    // (CoroutineScheduler) computes idle-worker keep-alive via
    // TimeUnit.SECONDS.toNanos(...); a bridged-to-zero result tripped
    // "Idle worker keep alive time 0 must be positive" IAE and killed
    // Compose composition (dooz M1/i.f chain).
    // ────────────────────────────────────────────────────────────────────────
    if (class_name.find("TimeUnit") != std::string::npos) {
        static const long long kToNanos[] = {
            1LL,                 // NANOS
            1000LL,              // MICROSECONDS
            1000000LL,           // MILLISECONDS
            1000000000LL,        // SECONDS
            60000000000LL,       // MINUTES
            3600000000000LL,     // HOURS
            86400000000000LL     // DAYS
        };
        auto unit_index = [&](const DalvikValue& v) -> int {
            std::string name;
            if (v.type == DalvikType::OBJECT_REF && v.object_id != 0 &&
                heap_.has_object(v.object_id)) {
                auto nf = heap_.get_object_field(v.object_id, "enum_name");
                if (nf && nf->type == DalvikType::STRING_REF) name = nf->string_val;
            }
            if (name == "NANOS") return 0;
            if (name == "MICROSECONDS") return 1;
            if (name == "MILLISECONDS") return 2;
            if (name == "SECONDS") return 3;
            if (name == "MINUTES") return 4;
            if (name == "HOURS") return 5;
            if (name == "DAYS") return 6;
            return -1;
        };
        auto saturating_mul = [](long long a, long long b) -> long long {
            if (a == 0 || b == 0) return 0;
            __int128 p = (__int128)a * (__int128)b;
            const __int128 kMax = (__int128)INT64_MAX;
            const __int128 kMin = (__int128)INT64_MIN;
            if (p > kMax) return INT64_MAX;
            if (p < kMin) return INT64_MIN;
            return (long long)p;
        };
        long long src_nanos_mult = 1LL;
        int uidx = -1;
        if (!args.empty()) uidx = unit_index(args[0]);
        if (uidx < 0) uidx = 3;  // defensive: treat unknown as SECONDS
        src_nanos_mult = kToNanos[uidx];

        long long src_val = args.size() >= 2 ? args[1].long_val : 0LL;
        if (args.size() < 2 || (args[1].type != DalvikType::INT64 &&
                                args[1].type != DalvikType::INT32)) {
            src_val = 0;  // only wide durations are meaningful here
        }

        long long out = 0;
        if (method == "toNanos") {
            out = saturating_mul(src_val, src_nanos_mult);
        } else if (method == "toMicros") {
            out = (src_nanos_mult >= 1000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 1000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 1000LL;
        } else if (method == "toMillis") {
            out = (src_nanos_mult >= 1000000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 1000000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 1000000LL;
        } else if (method == "toSeconds") {
            out = (src_nanos_mult >= 1000000000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 1000000000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 1000000000LL;
        } else if (method == "toMinutes") {
            out = (src_nanos_mult >= 60000000000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 60000000000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 60000000000LL;
        } else if (method == "toHours") {
            out = (src_nanos_mult >= 3600000000000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 3600000000000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 3600000000000LL;
        } else if (method == "toDays") {
            out = (src_nanos_mult >= 86400000000000LL)
                      ? saturating_mul(src_val, src_nanos_mult / 86400000000000LL)
                      : saturating_mul(src_val, src_nanos_mult) / 86400000000000LL;
        } else if (method == "convert") {
            // convert(long sourceDuration, TimeUnit sourceUnit) — receiver
            // unit is the TARGET granularity; args[2] is the source unit.
            long long src_mult = src_nanos_mult;   // args[0] = receiver = target
            long long in_nanos = saturating_mul(src_val, src_mult);
            long long out_mult = src_mult;
            if (args.size() >= 3) {
                int sidx = unit_index(args[2]);
                if (sidx >= 0) src_mult = kToNanos[sidx];
            } else if (args.size() >= 2 && unit_index(args[1]) >= 0) {
                // Some call shapes pass (unit, duration) — defensive.
                int sidx = unit_index(args[1]);
                src_mult = kToNanos[sidx];
            }
            in_nanos = saturating_mul(src_val, src_mult);
            out = out_mult ? in_nanos / out_mult : 0;
        } else {
            // Not a TimeUnit conversion — leave to later handlers.
            goto timeunit_not_handled;
        }
        result = DalvikValue::make_long(out);
        status = ApiCallTrace::Status::IMPLEMENTED;
        return true;
    }
    timeunit_not_handled:;

    // ────────────────────────────────────────────────────────────────────────
    // P1.4 — Resources.getIdentifier(String, String, String) → int
    // GATE A (issue #370 §7) — name→ID is a REQUIRED resolution direction
    // (R-4 law fix): AOSP ResourcesImpl.getIdentifier consults the FULL
    // resource table for ANY type (string/drawable/raw/layout/color/…),
    // not just inflated "id" tree nodes. Implementation: ARSC find_id over
    // the app package (package arg normalized; manifest package as the
    // fallback when the caller passes null/"android" mismatches), bounded
    // by the ARSC itself. The old behavior answered 0 for every non-id
    // type — programmatic resource binding was dead.
    // EXP-052: Log every resource identifier query for evidence.
    if (method == "getIdentifier" &&
        class_name.find("Resources") != std::string::npos) {
        // Args: (String name, String defType, String defPackage) — the
        // receiver (Resources) may occupy args[0] on instance dispatch.
        std::string name, defType, defPackage;
        {
            int s = 0;
            if (args.size() >= 4) s = 1;  // receiver slot present
            name = args.size() > (size_t)s ? args[s].string_val : "<unknown>";
            defType = args.size() > (size_t)s + 1 ? args[s + 1].string_val : "<unknown>";
            defPackage = args.size() > (size_t)s + 2 ? args[s + 2].string_val : "<unknown>";
        }
        int32_t found = 0;
        {
            auto& rt = resources::ResourceRuntime::instance();
            if (rt.loaded()) {
                std::vector<std::string> pkgs;
                if (!defPackage.empty() && defPackage != "<unknown>")
                    pkgs.push_back(defPackage);
                if (!package_name_.empty() && package_name_ != defPackage)
                    pkgs.push_back(package_name_);
                for (const auto& p : pkgs) {
                    auto id = rt.arsc().find_id(p, defType, name);
                    if (id) { found = (int32_t)*id; break; }
                }
            }
        }
        std::cerr << "[RES] getIdentifier name=\"" << name
                  << "\" defType=\"" << defType
                  << "\" defPackage=\"" << defPackage
                  << "\" → 0x" << std::hex << found << std::dec << std::endl;
        status = ApiCallTrace::Status::IMPLEMENTED;
        result = DalvikValue::make_int(found);
        return true;
    }

    // ────────────────────────────────────────────────────────────────────────
    // P1.5 — Resources.getDimensionPixelSize(int) → int
    // EXP-067: Real resolution via field_name_by_resid_ → resource_dimen_values_.
    // Falls back to 24px only if the dimension is not found.
    // ────────────────────────────────────────────────────────────────────────
    if (method == "getDimensionPixelSize" &&
        class_name.find("Resources") != std::string::npos) {
        // ────────────────────────────────────────────────────────────────
        // S67 FOUNDATION (A2 root cause, f32_dimen fixture 2026-09-19):
        // getDimensionPixelSize is a VIRTUAL Resources method — the
        // dispatch packs args[0] = this(Resources), args[1] = resid. The
        // handler previously read args[0].int_val, i.e. the receiver
        // object id (always 0 for the Resources singleton), so EVERY call
        // logged resid=0x0 and returned the silent 24px default while the
        // real resource id was in args[1]. Arg-index law matches the
        // sibling getResourceEntryName handler directly below.
        // Layer 2 of the fix (the seed): resource_dimen_values_ now holds
        // density-converted device px (see execution_engine.cpp seeding),
        // so the returned value satisfies the complexToDimensionPixelSize
        // contract instead of the raw dp mantissa.
        // ────────────────────────────────────────────────────────────────
        int32_t resid = 0;
        if (args.size() >= 2) resid = args[1].int_val;
        else if (args.size() == 1) resid = args[0].int_val;  // static-dispatch form
        int32_t dimen_val = 24;  // default 24px
        bool resolved = false;
        // ────────────────────────────────────────────────────────────────
        // S67 FOUNDATION (A2 layer 3, f32_dimen fixture): ARSC-FIRST
        // resolution — the same precedence the sibling getColor handler
        // above uses. The field_name_by_resid_ name-map path depends on
        // R$-class load-time seeding that not every SGET route triggers;
        // the ARSC itself is authoritative and independent of DEX R-class
        // parsing. Conversion through the canonical
        // complexToDimensionPixelSize law (unit decode × density + the one
        // rounding site). Fallback: name-map (density-converted seed).
        // ────────────────────────────────────────────────────────────────
        {
            auto& rt = resources::ResourceRuntime::instance();
            if (rt.loaded()) {
                auto v = rt.arsc().resolve_value((uint32_t)resid);
                if (v && v->type == resources::DataType::DIMENSION) {
                    dimen_val = resources::complex_unit_to_dimension_pixel_size(
                        v->dim_unit, v->dim_value, resources::DensityContext{});
                    resolved = true;
                }
            }
        }
        if (!resolved) {
            auto it = field_name_by_resid_.find(resid);
            if (it != field_name_by_resid_.end()) {
                const std::string& name = it->second;
                auto dit = resource_dimen_values_.find(name);
                if (dit != resource_dimen_values_.end()) {
                    dimen_val = dit->second;
                    resolved = true;
                }
            }
        }
        std::cerr << "[RES] getDimensionPixelSize resid=0x" << std::hex << resid << std::dec
                  << " → " << dimen_val << "px"
                  << (resolved ? " (ARSC/type-table)" : " (default 24px — not resolved)")
                  << std::endl;
        status = ApiCallTrace::Status::IMPLEMENTED;
        result = DalvikValue::make_int(dimen_val);
        return true;
    }

    // EXP-063: Resources.getResourceEntryName(int) → String
