            static thread_local const bool f235_diag = std::getenv("MINIANDROID_F235_DIAG") != nullptr;
            if (f235_diag && f235_sp++ < 40)
                std::cerr << "[F235-SPLIT] in=\"" << str.substr(0, 80)
                          << "\" delim=\"" << delim << "\" parts="
                          << parts.size()
                          << " caller=" << current_class_ << "."
                          << current_method_ << std::endl;
